from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_paren_groups(s):
        groups = []
        group = ''
        in_group = False
        for char in s:
            if char == '(':
                in_group = True
            elif char == ')':
                in_group = False
                groups.append(group)
                group = ''
            elif in_group:
                group += char
        return groups

    def remove_spaces(groups):
        return [group.replace(' ', '') for group in groups]

    def separate_groups(groups):
        return [group for group in groups]

    extracted_groups = extract_paren_groups(paren_string)
    cleaned_groups = remove_spaces(extracted_groups)
    distinct_groups = separate_groups(cleaned_groups)

    return distinct_groups

